struct Pair: Hashable {
    let a: Int, b: Int
    init(_ a: Int, _ b: Int) {
        self.a = min(a, b);
        self.b = max(a, b)
    }
}
typealias Mutex = Set<Pair>
struct GraphElement {
    let action: Int?, pre: State, add: State, del: State
}
struct GraphLevel {
    let elements: [GraphElement], mutex: Mutex
}
struct MemoKey: Hashable {
    let level: Int, goals: [Int]
}
final class Extractor {
    var levels: [GraphLevel] = [], memo: Set<MemoKey> = []
    var searched = 0, hits = 0, tried = 0
    func extract(_ level: Int, _ goals: [Int]) -> [[Int]]? {
        if level == 0 {
            return []
        }
        let key = MemoKey(level: level, goals: goals)
        if memo.contains(key) {
            hits += 1;
            return nil
        }
        searched += 1
        let result = assign(level, goals, 0, [])
        if result == nil {
            memo.insert(key)
        }
        return result
    }
    func assign(_ j: Int, _ goals: [Int], _ position: Int, _ chosen: [Int]) -> [[Int]]? {
        let level = levels[j - 1]
        var k = position
        while k < goals.count && chosen.contains(where: {
            level.elements[$0].add.contains(goals[k])
        }) {
            k += 1
        }
        if k == goals.count {
            let previous = Set(chosen.flatMap {
                level.elements[$0].pre
            }).sorted()
            guard var plan = extract(j - 1, previous) else {
                return nil
            }
            plan.append(chosen.compactMap {
                level.elements[$0].action
            }.sorted())
            return plan
        }
        let goal = goals[k]
        let achievers = level.elements.indices.filter {
            level.elements[$0].add.contains(goal)
        }.sorted {
            let a = level.elements[$0].action, b = level.elements[$1].action
            if (a == nil) != (b == nil) {
                return a == nil
            }
            return (a ?? 0) < (b ?? 0)
        }
        for x in achievers where chosen.allSatisfy({
            x == $0 || !level.mutex.contains(Pair(x, $0))
        }) {
            tried += 1
            if let plan = assign(j, goals, k + 1, chosen + [x]) {
                return plan
            }
        }
        return nil
    }
}
struct GraphResult {
    let search: SearchResult, layers: [[Int]], records: [String], hits: Int
}
enum GraphPlan {
    static func compatible(_ pre: State, _ mutex: Mutex) -> Bool {
        pre.allSatisfy {
            p in pre.allSatisfy {
                q in p == q || !mutex.contains(Pair(p, q))
            }
        }
    }
    static func run(_ actions: [Action], _ initial: State, _ goals: State, _ limit: Int) -> GraphResult {
        let extractor = Extractor()
        var facts = initial, mutex: Mutex = [], previous: (Int, Int)?, records: [String] = [], answer: [[Int]] = [], status = "level limit"
        for i in 0...limit {
            records.append("fact level \(i): facts=\(facts.count) mutexes=\(mutex.count)")
            let extract = goals.isSubset(of: facts) && compatible(goals, mutex)
            if extract {
                let before = extractor.searched, hits = extractor.hits, result = extractor.extract(i, goals.sorted())
                records.append("extract level \(i): \(result == nil ? "fail" : "success") searched=\(extractor.searched - before) memo_hits=\(extractor.hits - hits)")
                if let result {
                    answer = result;
                    status = "solved";
                    break
                }
            } else if let previous, previous.0 == facts.count && previous.1 == mutex.count {
                status = "unreachable";
                break
            }
            if i == limit {
                break
            }
            previous = (facts.count, mutex.count)
            var elements = actions.enumerated().filter {
                $0.element.pre.isSubset(of: facts) && compatible($0.element.pre, mutex)
            }.map {
                GraphElement(action: $0.offset, pre: $0.element.pre, add: $0.element.add, del: $0.element.del)
            }
            let real = elements.count
            for fact in facts.sorted() {
                elements.append(GraphElement(action: nil, pre: [fact], add: [fact], del: []))
            }
            var actionMutex: Mutex = []
            for x in elements.indices {
                for y in (x + 1)..<elements.count {
                    let a = elements[x], b = elements[y]
                    let interference = !a.del.isDisjoint(with: b.pre) || !a.del.isDisjoint(with: b.add) || !b.del.isDisjoint(with: a.pre) || !b.del.isDisjoint(with: a.add)
                    let competing = a.pre.contains {
                        p in b.pre.contains {
                            q in p != q && mutex.contains(Pair(p, q))
                        }
                    }
                    if interference || competing {
                        actionMutex.insert(Pair(x, y))
                    }
                }
            }
            records.append("action level \(i): actions=\(real) noops=\(facts.count) mutexes=\(actionMutex.count)")
            let next = Set(elements.flatMap(\.add)), values = next.sorted()
            var nextMutex: Mutex = []
            for x in values.indices {
                for y in (x + 1)..<values.count {
                    let p = values[x], q = values[y]
                    let impossible = elements.indices.filter {
                        elements[$0].add.contains(p)
                    }.allSatisfy {
                        a in elements.indices.filter {
                            elements[$0].add.contains(q)
                        }.allSatisfy {
                            b in a != b && actionMutex.contains(Pair(a, b))
                        }
                    }
                    if impossible {
                        nextMutex.insert(Pair(p, q))
                    }
                }
            }
            extractor.levels.append(GraphLevel(elements: elements, mutex: actionMutex))
            facts = next;
            mutex = nextMutex
        }
        return GraphResult(search: SearchResult(status: status, plan: answer.flatMap {
            $0
        }, expanded: extractor.searched, generated: extractor.tried), layers: answer, records: records, hits: extractor.hits)
    }
}

typealias State = Set<Int>
struct Action {
    let source: Int, name: String, args: [String], cost: Int
    var pre: State, neg: State, add: State, del: State
    var text: String {
        Atom(name, args).text
    }
}
struct Grounding {
    let facts: [Atom], actions: [Action], initial: State, goals: State, unreachable: [Atom]
    let stats: [[Int]], fluent: Set<String>, staticCount: Int
}
struct GroundCandidate {
    let source: Int, args: [String]
    var pre: Set<Atom> = [], neg: Set<Atom> = [], add: Set<Atom> = [], del: Set<Atom> = []
}
enum Grounder {
    static func subtype(_ domain: Domain, _ type: String, _ expected: String) -> Bool {
        var current = type
        while true {
            if current == expected {
                return true
            };
            guard let parent = domain.parents[current] else {
                return false
            };
            current = parent
        }
    }
    static func fluents(_ domain: Domain) -> Set<String> {
        Set(domain.actions.flatMap {
            $0.effects.map {
                $0.atom.predicate
            }
        })
    }
    static func ground(_ domain: Domain, _ problem: Problem) -> Grounding {
        let fluent = fluents(domain), initial = Set(problem.initial)
        var stats = Array(repeating: [0, 0, 0], count: domain.actions.count), candidates: [GroundCandidate] = []
        for (source, action) in domain.actions.enumerated() {
            let choices = action.parameters.map {
                parameter in problem.objects.filter {
                    subtype(domain, $0.1, parameter.1)
                }.map {
                    $0.0
                }
            }
            var all: [[String]] = [], current: [String] = []
            func combinations(_ i: Int) {
                if i == choices.count {
                    all.append(current);
                    return
                }
                for object in choices[i] {
                    current.append(object);
                    combinations(i + 1);
                    current.removeLast()
                }
            }
            combinations(0)
            stats[source][0] = all.count
            for args in all {
                let values = Dictionary(uniqueKeysWithValues: zip(action.parameters.map {
                    $0.0
                }, args))
                var candidate = GroundCandidate(source: source, args: args), valid = true
                for literal in action.pre {
                    let atom = literal.atom.replace(values)
                    if atom.predicate == "=" || !fluent.contains(atom.predicate) {
                        let truth = atom.predicate == "=" ? atom.terms[0] == atom.terms[1] : initial.contains(atom)
                        if truth == literal.negative {
                            valid = false;
                            break
                        }
                    } else if literal.negative {
                        candidate.neg.insert(atom)
                    }
                    else {
                        candidate.pre.insert(atom)
                    }
                }
                if !valid {
                    continue
                }
                for literal in action.effects {
                    let atom = literal.atom.replace(values)
                    if literal.negative {
                        candidate.del.insert(atom)
                    } else {
                        candidate.add.insert(atom)
                    }
                }
                candidate.del.subtract(candidate.add)
                stats[source][1] += 1
                candidates.append(candidate)
            }
        }
        var reachable = Set(initial.filter {
            fluent.contains($0.predicate)
        }), kept: Set<Int> = []
        while true {
            let before = kept.count
            for (i, candidate) in candidates.enumerated() where candidate.pre.isSubset(of: reachable) {
                kept.insert(i);
                reachable.formUnion(candidate.add)
            }
            if kept.count == before {
                break
            }
        }
        let predicates = Dictionary(uniqueKeysWithValues: domain.predicates.enumerated().map {
            ($0.element.name, $0.offset)
        })
        let objects = Dictionary(uniqueKeysWithValues: problem.objects.enumerated().map {
            ($0.element.0, $0.offset)
        })
        let facts = reachable.sorted {
            let a = predicates[$0.predicate]!, b = predicates[$1.predicate]!
            return a == b ? $0.terms.map {
                objects[$0]!
            }.lexicographicallyPrecedes($1.terms.map {
                objects[$0]!
            }) : a < b
        }
        let numbering = Dictionary(uniqueKeysWithValues: facts.enumerated().map {
            ($0.element, $0.offset)
        })
        func numbers(_ atoms: Set<Atom>) -> State {
            Set(atoms.compactMap {
                numbering[$0]
            })
        }
        var actions: [Action] = []
        for i in kept.sorted() {
            let candidate = candidates[i], action = domain.actions[candidate.source]
            stats[candidate.source][2] += 1
            actions.append(Action(source: candidate.source, name: action.name, args: candidate.args, cost: action.cost, pre: numbers(candidate.pre), neg: numbers(candidate.neg), add: numbers(candidate.add), del: numbers(candidate.del)))
        }
        var goals: State = [], unreachable: [Atom] = []
        for atom in problem.goals {
            if let i = numbering[atom] {
                goals.insert(i)
            }
            else if fluent.contains(atom.predicate) || !initial.contains(atom) {
                unreachable.append(atom)
            }
        }
        return Grounding(facts: facts, actions: actions, initial: numbers(initial), goals: goals, unreachable: unreachable, stats: stats, fluent: fluent, staticCount: problem.initial.filter {
            !fluent.contains($0.predicate)
        }.count)
    }
}

enum Heuristics {
    static let infinity = 1_000_000_000_000
    static func aggregate(_ values: [Int], _ maximum: Bool) -> Int {
        if values.contains(where: {
            $0 >= infinity
        }) {
            return infinity
        }
        return maximum ? values.max() ?? 0 : values.reduce(0, +)
    }
    static func costs(_ grounding: Grounding, _ state: State, _ maximum: Bool) -> [Int] {
        var costs = Array(repeating: infinity, count: grounding.facts.count)
        for fact in state {
            costs[fact] = 0
        }
        while true {
            var changed = false
            for action in grounding.actions {
                let previous = aggregate(action.pre.sorted().map {
                    costs[$0]
                }, maximum)
                if previous >= infinity {
                    continue
                }
                let value = previous + action.cost
                for fact in action.add where value < costs[fact] {
                    costs[fact] = value;
                    changed = true
                }
            }
            if !changed {
                return costs
            }
        }
    }
    static func relaxed(_ grounding: Grounding, _ state: State) -> (Int, [Int], [Int]) {
        let costs = self.costs(grounding, state, false)
        if grounding.goals.contains(where: {
            costs[$0] >= infinity
        }) {
            return (infinity, [], [])
        }
        func achiever(_ fact: Int) -> Int {
            grounding.actions.indices.filter {
                grounding.actions[$0].add.contains(fact) && grounding.actions[$0].pre.allSatisfy {
                    costs[$0] < infinity
                }
            }.min {
                let a = grounding.actions[$0], b = grounding.actions[$1]
                let x = a.cost + a.pre.reduce(0) {
                    $0 + costs[$1]
                }, y = b.cost + b.pre.reduce(0) {
                    $0 + costs[$1]
                }
                return x == y ? $0 < $1 : x < y
            }!
        }
        var chosen: State = [], pending = grounding.goals.subtracting(state).sorted()
        while let fact = pending.popLast() {
            let action = achiever(fact);
            if chosen.insert(action).inserted {
                pending += grounding.actions[action].pre.subtracting(state).sorted()
            }
        }
        let plan = chosen.sorted(), helpful = plan.filter {
            Search.applicable(grounding.actions[$0], state)
        }
        return (plan.reduce(0) {
            $0 + grounding.actions[$1].cost
        }, plan, helpful)
    }
    static func landmarks(_ grounding: Grounding, _ state: State) -> State? {
        var factLevel = Array(repeating: Int.max, count: grounding.facts.count), actionLevel = Array(repeating: Int.max, count: grounding.actions.count)
        for fact in state {
            factLevel[fact] = 0
        }
        var k = 0
        while true {
            var added = false
            for (i, action) in grounding.actions.enumerated() where actionLevel[i] == Int.max && action.pre.allSatisfy({
                factLevel[$0] <= k
            }) {
                actionLevel[i] = k
                for fact in action.add where factLevel[fact] == Int.max {
                    factLevel[fact] = k + 1;
                    added = true
                }
            }
            if !added {
                break
            }
            k += 1
        }
        if grounding.goals.contains(where: {
            factLevel[$0] == Int.max
        }) {
            return nil
        }
        var landmarks = grounding.goals.subtracting(state)
        while true {
            let before = landmarks.count
            for fact in landmarks.sorted() {
                let achievers = grounding.actions.indices.filter {
                    actionLevel[$0] != Int.max && actionLevel[$0] + 1 == factLevel[fact] && grounding.actions[$0].add.contains(fact)
                }
                var candidates = grounding.actions[achievers[0]].pre
                for i in achievers.dropFirst() {
                    candidates.formIntersection(grounding.actions[i].pre)
                }
                for candidate in candidates.subtracting(state).sorted() where !landmarks.contains(candidate) {
                    var reachable = state
                    while true {
                        let old = reachable.count
                        for action in grounding.actions where !action.add.contains(candidate) && action.pre.isSubset(of: reachable) {
                            reachable.formUnion(action.add)
                        }
                        if old == reachable.count {
                            break
                        }
                    }
                    if !grounding.goals.isSubset(of: reachable) {
                        landmarks.insert(candidate)
                    }
                }
            }
            if before == landmarks.count {
                return landmarks
            }
        }
    }
    static func value(_ grounding: Grounding, _ state: State, _ name: String) -> Int {
        switch name {
            case "none": return 0
            case "goalcount": return grounding.goals.subtracting(state).count
            case "hmax", "hadd": let maximum = name == "hmax", costs = self.costs(grounding, state, maximum);
            return aggregate(grounding.goals.sorted().map {
                costs[$0]
            }, maximum)
            case "ff": return relaxed(grounding, state).0
            default: return landmarks(grounding, state)?.count ?? infinity
        }
    }
    static func values(_ grounding: Grounding, _ state: State) -> [Int] {
        ["goalcount", "hmax", "hadd", "ff", "lmcount"].map {
            value(grounding, state, $0)
        }
    }
}

import Foundation
func arguments(_ domain: Domain, _ args: [String], _ expected: [String], _ table: [String: String], _ noun: String) -> String? {
    if args.count != expected.count {
        return "expected \(expected.count) arguments, got \(args.count)"
    }
    for (i, pair) in zip(args, expected).enumerated() {
        let (name, type) = pair
        guard let actual = table[name] else {
            return "unknown \(noun) \(name)"
        }
        if !Grounder.subtype(domain, actual, type) {
            return "argument \(i + 1) (\(name)) is not of type \(type)"
        }
    }
    return nil
}
func atomError(_ domain: Domain, _ atom: Atom, _ table: [String: String], _ noun: String, _ equality: Bool) -> String? {
    let types: [String]
    if equality && atom.predicate == "=" {
        types = ["object", "object"]
    }
    else if let predicate = domain.predicates.first(where: {
        $0.name == atom.predicate
    }) {
        types = predicate.types
    }
    else {
        return "unknown predicate \(atom.predicate)"
    }
    return arguments(domain, atom.terms, types, table, noun)
}
func validateDomain(_ domain: Domain) {
    var actions: [Schema] = []
    for action in domain.actions {
        let table = Dictionary(uniqueKeysWithValues: action.parameters)
        var error = action.parameters.first {
            !domain.typeOrder.contains($0.1)
        }.map {
            "unknown type \($0.1)"
        }
        if error == nil {
            for literal in action.pre + action.effects {
                if let reason = atomError(domain, literal.atom, table, "variable", true) {
                    error = "\(literal.atom.text): \(reason)";
                    break
                }
            }
        }
        if let error {
            domain.diagnostics.append("error: action \(action.name): \(error)")
        } else {
            actions.append(action)
        }
    }
    domain.actions = actions
    for predicate in domain.predicates where !domain.actions.contains(where: {
        ($0.pre + $0.effects).contains {
            $0.atom.predicate == predicate.name
        }
    }) {
        domain.diagnostics.append("warning: predicate \(predicate.name) is not used by any action")
    }
}
func validateProblem(_ domain: Domain, _ problem: Problem) {
    let table = Dictionary(uniqueKeysWithValues: problem.objects)
    for side in 0..<2 {
        let original = side == 0 ? problem.initial : problem.goals
        var seen: Set<Atom> = [], kept: [Atom] = []
        for atom in original {
            let error = atomError(domain, atom, table, "object", false) ?? (seen.contains(atom) ? "duplicate" : nil)
            if let error {
                problem.diagnostics.append("warning: \(side == 0 ? "init" : "goal") \(atom.text): \(error)")
            }
            else {
                seen.insert(atom);
                kept.append(atom)
            }
        }
        if side == 0 {
            problem.initial = kept
        } else {
            problem.goals = kept
        }
    }
}
func list(_ heading: String, _ values: [String]) -> String {
    heading + " " + (values.isEmpty ? "-" : values.joined(separator: " "))
}
func numbers(_ values: State) -> String {
    values.isEmpty ? "-" : values.sorted().map(String.init).joined(separator: ",")
}
func hText(_ value: Int) -> String {
    value >= Heuristics.infinity ? "inf" : String(value)
}
func hValues(_ values: [Int]) -> String {
    zip(["goalcount", "hmax", "hadd", "ff", "lmcount"], values).map {
        "\($0.0)=\(hText($0.1))"
    }.joined(separator: " ")
}
func cost(_ grounding: Grounding, _ plan: [Int]) -> Int {
    plan.reduce(0) {
        $0 + grounding.actions[$1].cost
    }
}
func domainReport(_ domain: Domain) -> [String] {
    var lines = ["== domain \(domain.name) =="] + domain.diagnostics
    for type in domain.typeOrder {
        var chain = [type], current = type
        while let parent = domain.parents[current] {
            chain.append(parent);
            current = parent
        }
        lines.append("type " + chain.joined(separator: " < "))
    }
    let fluent = Grounder.fluents(domain)
    for predicate in domain.predicates {
        lines.append("predicate \(predicate.name)/\(predicate.types.count) \(fluent.contains(predicate.name) ? "fluent" : "static")")
    }
    for action in domain.actions {
        lines.append("action \(action.name)/\(action.parameters.count) cost=\(action.cost) pre=\(action.pre.count) add=\(action.effects.filter { !$0.negative }.count) del=\(action.effects.filter(\.negative).count)")
    }
    return lines
}
func groundingReport(_ domain: Domain, _ problem: Problem, _ g: Grounding) -> [String] {
    var lines = ["", "== problem \(problem.name) =="] + problem.diagnostics + ["objects: \(problem.objects.count)"]
    for type in domain.typeOrder {
        lines.append(list("  \(type):", problem.objects.filter {
            Grounder.subtype(domain, $0.1, type)
        }.map {
            $0.0
        }))
    }
    lines.append("static facts: \(g.staticCount)")
    for (i, action) in domain.actions.enumerated() {
        let s = g.stats[i];
        lines.append("schema \(action.name): assignments=\(s[0]) candidates=\(s[1]) reachable=\(s[2])")
    }
    lines += ["candidates: \(g.stats.reduce(0) { $0 + $1[1] }) reachable: \(g.actions.count)", "facts: \(g.facts.count) init: \(g.initial.count) goals: \(g.goals.count)"]
    for atom in g.unreachable {
        lines.append("unreachable goal: \(atom.text)")
    }
    lines.append(list("facts by predicate:", domain.predicates.filter {
        g.fluent.contains($0.name)
    }.map {
        p in "\(p.name)=\(g.facts.filter { $0.predicate == p.name }.count)"
    }))
    lines.append("facts:")
    for (i, atom) in g.facts.enumerated() {
        lines.append("  \(i) \(atom.text)")
    }
    lines.append("actions:")
    for (i, action) in g.actions.enumerated() {
        lines.append("  \(i) \(action.text) cost=\(action.cost) pre=\(numbers(action.pre)) neg=\(numbers(action.neg)) add=\(numbers(action.add)) del=\(numbers(action.del))")
    }
    return lines
}
struct Validation {
    let status: String, messages: [String], correct: Int
    var verdict: String {
        status == "valid" ? "valid \(messages[0])" : "\(status): \(messages[0])"
    }
}
func validateSteps(_ domain: Domain, _ problem: Problem, _ steps: [Atom]) -> Validation {
    var world = Set(problem.initial), cost = 0
    let table = Dictionary(uniqueKeysWithValues: problem.objects)
    for (k, step) in steps.enumerated() {
        guard let action = domain.actions.first(where: {
            $0.name == step.predicate
        }) else {
            return Validation(status: "invalid", messages: ["step \(k + 1) \(step.text): unknown action \(step.predicate)"], correct: k)
        }
        if let error = arguments(domain, step.terms, action.parameters.map {
            $0.1
        }, table, "object") {
            return Validation(status: "invalid", messages: ["step \(k + 1) \(step.text): \(error)"], correct: k)
        }
        let values = Dictionary(uniqueKeysWithValues: zip(action.parameters.map {
            $0.0
        }, step.terms))
        for literal in action.pre {
            let literal = literal.replace(values), atom = literal.atom
            let truth = atom.predicate == "=" ? atom.terms[0] == atom.terms[1] : world.contains(atom)
            if truth == literal.negative {
                return Validation(status: "invalid", messages: ["step \(k + 1) \(step.text): precondition \(literal.text) is false"], correct: k)
            }
        }
        for literal in action.effects where literal.negative {
            world.remove(literal.atom.replace(values))
        }
        for literal in action.effects where !literal.negative {
            world.insert(literal.atom.replace(values))
        }
        cost += action.cost
    }
    let missing = problem.goals.filter {
        !world.contains($0)
    }.map {
        "unsatisfied goal \($0.text)"
    }
    return missing.isEmpty ? Validation(status: "valid", messages: ["length=\(steps.count) cost=\(cost)"], correct: steps.count) : Validation(status: "goal not reached", messages: missing, correct: steps.count)
}
func steps(_ g: Grounding, _ plan: [Int]) -> [Atom] {
    plan.map {
        Atom(g.actions[$0].name, g.actions[$0].args)
    }
}
func mapSteps(_ g: Grounding, _ steps: [Atom]) -> [Int] {
    steps.map {
        step in g.actions.firstIndex {
            $0.name == step.predicate && $0.args == step.terms
        }!
    }
}
func interfere(_ a: Action, _ b: Action) -> Bool {
    !a.del.isDisjoint(with: b.pre) || !a.del.isDisjoint(with: b.add) || !b.del.isDisjoint(with: a.pre) || !b.del.isDisjoint(with: a.add) || !a.add.isDisjoint(with: b.neg) || !b.add.isDisjoint(with: a.neg)
}
func parallel(_ g: Grounding, _ plan: [Int]) -> [[Int]] {
    var levels: [Int] = []
    for (j, action) in plan.enumerated() {
        var level = 0
        for i in 0..<j {
            let a = g.actions[plan[i]], b = g.actions[action]
            if !a.add.isDisjoint(with: b.pre) || !a.del.isDisjoint(with: b.neg) || interfere(a, b) {
                level = max(level, levels[i])
            }
        }
        levels.append(level + 1)
    }
    var layers = Array(repeating: [Int](), count: levels.max() ?? 0)
    for (i, action) in plan.enumerated() {
        layers[levels[i] - 1].append(action)
    }
    return layers
}
func parallelVerdict(_ g: Grounding, _ layers: [[Int]]) -> String {
    var state = g.initial
    for (k, layer) in layers.enumerated() {
        let bad = layer.enumerated().contains {
            i, a in layer.dropFirst(i + 1).contains {
                interfere(g.actions[a], g.actions[$0])
            }
        }
        if layer.contains(where: {
            !Search.applicable(g.actions[$0], state)
        }) || bad {
            return "invalid at layer \(k + 1)"
        }
        state.subtract(Set(layer.flatMap {
            g.actions[$0].del
        }))
        for action in layer {
            state.formUnion(g.actions[action].add)
        }
    }
    return g.goals.isSubset(of: state) ? "valid" : "goal not reached"
}
func improve(_ g: Grounding, _ input: [Int]) -> [Int] {
    var plan = input, i = 0
    while i < plan.count {
        var state = g.initial
        for action in plan.prefix(i) {
            state = Search.apply(g.actions[action], state)
        }
        var next = Array(plan.prefix(i))
        for action in plan.dropFirst(i + 1) where Search.applicable(g.actions[action], state) {
            state = Search.apply(g.actions[action], state);
            next.append(action)
        }
        if g.goals.isSubset(of: state) {
            plan = next
        } else {
            i += 1
        }
    }
    return plan
}
func transformed(_ g: Grounding) -> ([Action], State, Int) {
    let negatives = Set(g.actions.flatMap(\.neg)).sorted(), complements = Dictionary(uniqueKeysWithValues: negatives.enumerated().map {
        ($0.element, g.facts.count + $0.offset)
    })
    var initial = g.initial, actions = g.actions
    for (fact, complement) in complements where !initial.contains(fact) {
        initial.insert(complement)
    }
    for i in actions.indices {
        let original = g.actions[i]
        actions[i].pre.formUnion(original.neg.map {
            complements[$0]!
        })
        actions[i].add.formUnion(original.del.compactMap {
            complements[$0]
        })
        actions[i].del.formUnion(original.add.compactMap {
            complements[$0]
        })
    }
    return (actions, initial, negatives.count)
}
struct Params {
