        predicate = a[0].word;
        terms = a.dropFirst().map(\.word)
    }
    var text: String {
        "(" + ([predicate] + terms).joined(separator: " ") + ")"
    }
    func replace(_ values: [String: String]) -> Self {
        Self(predicate, terms.map {
            values[$0]!
        })
    }
}
struct Literal {
    let atom: Atom, negative: Bool
    var text: String {
        negative ? "(not \(atom.text))" : atom.text
    }
    func replace(_ values: [String: String]) -> Self {
